import { step, glide } from "../world/movement.js";
import { bounce, keepInside } from "../world/bounds.js";

const BODY = "purple";
const TENTACLE = "lavender";

export function spawn() {
  // start near the middle, drifting downwards
  return { x: 400, y: 250, vx: 0, vy: 1, energy: undefined };
}

export function update(jelly, world) {
  // drift up and down, slowly lose speed then step
  glide(jelly, 0.99);
  step(jelly);
  // bounce off top and bottom of water
  bounce(jelly);
  // keep inside horizontal bounds
  keepInside(jelly);
}

export function draw(jelly, pen) {
  // draw a simple jellyfish: dome and tentacles
  pen.fill(BODY);
  pen.ellipse(0, 0, 30, 20);
  pen.fill(TENTACLE);
  // three tentacles
  pen.line(-10, 10, -10, 30);
  pen.line(0, 10, 0, 35);
  pen.line(10, 10, 10, 30);
}

export const count = 2;

