import { FLOOR_Y } from "../world/bounds.js";

const BODY = "orange";

export function spawn() {
  // sits on the sand surface
  return { y: FLOOR_Y - 4, vx: 0 };
}

export function update() {
  // no movement, just exist
}

export function draw(starfish, pen) {
  // slowly turn based on age
  const angle = (starfish.age || 0) * 0.02; // radians per tick
  pen.turn(angle);
  pen.fill(BODY);
  // draw a simple 5‑point star
  pen.beginPath();
  for (let i = 0; i < 5; i++) {
    const outer = 12;
    const inner = 5;
    const a = i * (Math.PI * 2) / 5;
    pen.lineTo(Math.cos(a) * outer, Math.sin(a) * outer);
    pen.lineTo(Math.cos(a + Math.PI / 5) * inner, Math.sin(a + Math.PI / 5) * inner);
  }
  pen.closePath();
  pen.fill();
  pen.turn(-angle); // reset rotation for next draw calls
}

