import { FLOOR_Y, keepInside } from "../world/bounds.js";
import { step } from "../world/movement.js";

// Colours
const BODY = "#c2a35f"; // sand‑like
const SPIKE = "#8b5a2b";

// A sea urchin spawns on the sand, not moving.
export function spawn() {
  return { x: Math.random() * 800, y: FLOOR_Y, vx: 0, vy: 0 };
}

export function update(creature, world) {
  // stay on the sand
  keepInside(creature);
  // optional tiny drift
  creature.vx = Math.sin(creature.age * 0.01) * 0.2;
  step(creature);
}

export function draw(creature, pen) {
  // draw body
  pen.fill(BODY);
  pen.ellipse(0, 0, 20, 12);
  // draw spines rotating with age
  const spikes = 12;
  const angleStep = (Math.PI * 2) / spikes;
  const rotation = creature.age * 0.05;
  pen.stroke(SPIKE);
  // pen.strokeWeight(2);
  for (let i = 0; i < spikes; i++) {
    const a = i * angleStep + rotation;
    const x = Math.cos(a) * 12;
    const y = Math.sin(a) * 8;
    pen.line(0, 0, x, y);
  }
}

export const count = 3;

