import { step } from "../world/movement.js";
import { wrap } from "../world/bounds.js";

const BODY = "orange";
const SPOUT = "yellow";

export const count = 4;

export function spawn() {
  // radius is the base size; puffed state will be handled in update
  return { vx: 1, radius: 10, puffed: false };
}

export function update(puffer, world) {
  // Find the distance to the closest other creature
  let minDist = Infinity;
  for (const other of world.creatures) {
    if (other.id === puffer.id) continue;
    const dx = other.x - puffer.x;
    const dy = other.y - puffer.y;
    const dist = Math.hypot(dx, dy);
    if (dist < minDist) minDist = dist;
  }
  // If another creature is within 30 units, puff up
  puffer.puffed = minDist < 30;
  // Adjust radius based on puffed state
  puffer.radius = puffer.puffed ? 20 : 10;

  step(puffer);
  wrap(puffer);
}

export function draw(puffer, pen) {
  // Draw the body
  pen.fill(BODY);
  pen.ellipse(0, 0, puffer.radius * 2, puffer.radius * 2);
  // If puffed, add spines
  if (puffer.puffed) {
    pen.fill(SPOUT);
    // simple spines as lines radiating outward
    for (let i = 0; i < 8; i++) {
      const angle = (i * Math.PI) / 4;
      const x1 = Math.cos(angle) * puffer.radius;
      const y1 = Math.sin(angle) * puffer.radius;
      const x2 = Math.cos(angle) * (puffer.radius + 5);
      const y2 = Math.sin(angle) * (puffer.radius + 5);
      pen.line(x1, y1, x2, y2);
    }
  }
}

