// A lobster that walks along the sand and turns around at the walls.
import { step } from "../world/movement.js";
import { POOL_WIDTH, FLOOR_Y } from "../world/bounds.js";

// Colours and shape constants.
const BODY = { fill: "#FF8800", stroke: "#AA5500" };
const CLAW = { fill: "#CC6600", stroke: "#884400" };

// Optional: how many lobsters to create (default 1‑8).
export const count = 3;

export function spawn() {
  // Start near the top of the sand, moving left or right.
  return {
    x: Math.random() * POOL_WIDTH,
    y: FLOOR_Y + 20,
    vx: (Math.random() < 0.5 ? -1 : 1) * 30,
    vy: 0,
    kind: "lobster",
  };
}

export function update(lobster) {
  // Move according to velocity.
  step(lobster);
  // Turn around when hitting a side wall.
  if (lobster.x < 0 || lobster.x > POOL_WIDTH) {
    lobster.vx = -lobster.vx;
  }
  // Keep inside horizontal bounds.
  lobster.x = Math.max(0, Math.min(POOL_WIDTH, lobster.x));
  // Keep on the sand (just clamp y, no vertical movement).
  lobster.y = Math.max(FLOOR_Y, Math.min(FLOOR_Y + 40, lobster.y));
}

export function draw(lobster, pen) {
  pen.save();
  pen.translate(lobster.x, lobster.y);
  // Body
  pen.fill(BODY.fill).stroke(BODY.stroke);
  pen.ellipse(0, 0, 30, 15);
  // Simple claw
  pen.fill(CLAW.fill).stroke(CLAW.stroke);
  pen.rect(15, -5, 8, 10);
  pen.restore();
}

