// Crab creature
// Hides in its shell when energy drops below 30% of ENERGY_MAX.

import { ENERGY_MAX } from "../world/energy.js";
import { step } from "../world/movement.js";
import { bounce } from "../world/bounds.js";

// Colours
const SHELL_COLOR = "#8B4513"; // brown
const BODY_COLOR = "#FF6347"; // tomato red

/**
 * Spawn a new crab.
 * Returns an object with initial properties.
 */
export function spawn(world) {
  // Start near the center with a random direction.
  const x = 0;
  const y = 0;
  const speed = 0.5 + Math.random() * 0.5; // 0.5‑1.0 units per tick
  const angle = Math.random() * Math.PI * 2;
  return {
    x,
    y,
    vx: Math.cos(angle) * speed,
    vy: Math.sin(angle) * speed,
    kind: "crab",
    hidden: false,
    // optional energy, let world handle cost
    energy: ENERGY_MAX,
  };
}

/**
 * Update the crab each tick.
 * If energy is below 30% of ENERGY_MAX, hide in shell.
 */
export function update(creature, world) {
  // Move
  step(creature);
  bounce(creature, world);

  // Hide when low energy
  const hideThreshold = ENERGY_MAX * 0.3;
  if (creature.energy !== undefined) {
    creature.hidden = creature.energy < hideThreshold;
  }
}

/**
 * Draw the crab.
 * When hidden, draw only the shell (a circle).
 * Otherwise draw a simple crab shape.
 */
export function draw(creature, pen, world) {
  pen.save();
  pen.translate(creature.x, creature.y);

