import { ENERGY_MAX } from "../world/energy.js";
import { step, steer, glide } from "../world/movement.js";
import { wrap } from "../world/bounds.js";

// Colours
const SHELL = "brown";
const CLAW = "red";
const BODY = "orange";

export const count = 3;

export function spawn() {
  // start with full energy and a small forward velocity
  return { vx: 1, energy: ENERGY_MAX, hidden: false };
}

export function update(crab, world) {
  // Hide when energy drops below 30% of max
  if (crab.energy < ENERGY_MAX * 0.3) {
    crab.hidden = true;
    crab.vx = 0;
    crab.vy = 0;
  } else {
    crab.hidden = false;
    // simple wandering: steer toward a random point ahead
    const targetX = crab.x + (Math.random() - 0.5) * 200;
    const targetY = crab.y + (Math.random() - 0.5) * 200;
    steer(crab, targetX, targetY, 0.1);
    glide(crab, 0.99);
    step(crab);
    wrap(crab);
  }
}

